function createDoubleArrow(length = 0.35, shaftRadius = 0.018, color = red, opacity = 1) {
  const g = new THREE.Group();
  const coneH = length * 0.18;
  const shaftLen = Math.max(0.01, length - 2 * coneH);
  const material = matBasic(color, { transparent: opacity < 1, opacity });
