  coneTop.position.y = length / 2 - coneH / 2;
  g.add(coneTop);
  const coneBot = new THREE.Mesh(new THREE.ConeGeometry(shaftRadius * 3.0, coneH, 16), material);
  coneBot.position.y = -length / 2 + coneH / 2;
  coneBot.rotation.z = Math.PI;
  g.add(coneBot);
  return g;
}

function setArrowAngle(group, deg) {
