const red = 0xe31b23;
const beamColor = 0xe8c36b;
const glowColor = 0xf2f36b;
const rimColor = 0x555555;
const glassColor = 0xbfe6e6;

scene.add(new THREE.AmbientLight(0xffffff, 1.18));
const lampLight = new THREE.PointLight(0xfff39a, 1.35, 4.5);
lampLight.position.set(-3.83, 0.13, 0.22);
scene.add(lampLight);
const keyLight = new THREE.DirectionalLight(0xffffff, 1.0);
keyLight.position.set(1.5, 3.6, 4.5);
scene.add(keyLight);

function matBasic(color, opts = {}) {
  return new THREE.MeshBasicMaterial({
    color,
    transparent: opts.transparent ?? false,
    opacity: opts.opacity ?? 1,
    side: opts.side ?? THREE.FrontSide,
    depthWrite: opts.depthWrite ?? true
  });
}

function lineMat(color, opts = {}) {
  return new THREE.LineBasicMaterial({
    color,
    transparent: opts.transparent ?? false,
    opacity: opts.opacity ?? 1
  });
}

function createDoubleArrow(length = 0.35, shaftRadius = 0.018, color = red, opacity = 1) {
  const g = new THREE.Group();
  const coneH = length * 0.18;
  const shaftLen = Math.max(0.01, length - 2 * coneH);
  const material = matBasic(color, { transparent: opacity < 1, opacity });
  const shaft = new THREE.Mesh(new THREE.CylinderGeometry(shaftRadius, shaftRadius, shaftLen, 12), material);
  g.add(shaft);
  const coneTop = new THREE.Mesh(new THREE.ConeGeometry(shaftRadius * 3.1, coneH, 18), material);
  coneTop.position.y = length / 2 - coneH / 2;
  g.add(coneTop);
  const coneBot = new THREE.Mesh(new THREE.ConeGeometry(shaftRadius * 3.1, coneH, 18), material);
  coneBot.position.y = -length / 2 + coneH / 2;
  coneBot.rotation.z = Math.PI;
  g.add(coneBot);
  return g;
}

function setArrowAngle(group, deg) {
  group.rotation.x = -THREE.MathUtils.degToRad(deg);
}

function setGroupOpacity(group, opacity) {
  group.traverse(obj => {
    if (obj.material) {
      obj.material.transparent = opacity < 1;
      obj.material.opacity = opacity;
      obj.material.needsUpdate = true;
    }
  });
}

function makeTaperedRibbon(x0, x1, h0, h1, zHalf = 0.045, opacity = 0.48) {
  const verts = new Float32Array([
    x0, -h0, -zHalf,  x1, -h1, -zHalf,  x1,  h1, -zHalf,  x0,  h0, -zHalf,
    x0, -h0,  zHalf,  x1, -h1,  zHalf,  x1,  h1,  zHalf,  x0,  h0,  zHalf
  ]);
  const idx = [
    0, 1, 2, 0, 2, 3,
    4, 6, 5, 4, 7, 6,
    0, 4, 5, 0, 5, 1,
    3, 2, 6, 3, 6, 7,
    1, 5, 6, 1, 6, 2,
    0, 3, 7, 0, 7, 4
  ];
  const geom = new THREE.BufferGeometry();
  geom.setAttribute('position', new THREE.BufferAttribute(verts, 3));
  geom.setIndex(idx);
  geom.computeVertexNormals();
  const mesh = new THREE.Mesh(
    geom,
    matBasic(beamColor, { transparent: true, opacity, side: THREE.DoubleSide, depthWrite: false })
  );
  scene.add(mesh);

  const softGeom = geom.clone();
  const softMesh = new THREE.Mesh(
    softGeom,
    matBasic(beamColor, { transparent: true, opacity: opacity * 0.26, side: THREE.DoubleSide, depthWrite: false })
  );
  softMesh.scale.set(1, 1.42, 1.55);
  scene.add(softMesh);
  return mesh;
}

function makeDiscFace(x, radius, color, opacity = 0.88) {
  const mesh = new THREE.Mesh(
    new THREE.CylinderGeometry(radius, radius, 0.16, 96),
    new THREE.MeshBasicMaterial({ color, transparent: opacity < 1, opacity, side: THREE.DoubleSide, depthWrite: false })
  );
  mesh.rotation.z = Math.PI / 2;
  mesh.position.x = x;
  scene.add(mesh);
  return mesh;
}

function makeRim(x, radius, tubeRadius = 0.055) {
  const rim = new THREE.Mesh(
    new THREE.TorusGeometry(radius, tubeRadius, 18, 120),
    matBasic(rimColor)
  );
  rim.rotation.y = Math.PI / 2;
  rim.position.x = x;
  scene.add(rim);
  return rim;
}

function makeStripeGroup(x, radius, spacing, colorA, colorB, opacity = 1) {
  const g = new THREE.Group();
  g.position.set(x, 0, 0);
  let idx = 0;
  for (let z = -radius * 0.88; z <= radius * 0.88 + 1e-6; z += spacing) {
    const yLen = Math.sqrt(Math.max(0, radius * radius - z * z)) * 0.94;
    const pts = [new THREE.Vector3(0, -yLen, z), new THREE.Vector3(0, yLen, z)];
    const line = new THREE.Line(
      new THREE.BufferGeometry().setFromPoints(pts),
      lineMat(idx % 2 ? colorA : colorB, { transparent: opacity < 1, opacity })
    );
    g.add(line);
    idx++;
  }
  scene.add(g);
  return g;
}

const glowGroup = new THREE.Group();
for (const [r, op] of [[1.05, 0.12], [0.78, 0.17], [0.52, 0.23]]) {
  const glow = new THREE.Mesh(
    new THREE.CircleGeometry(r, 96),
