  );
  glow.position.set(-3.88, 0.17, -0.22);
  glowGroup.add(glow);
}
scene.add(glowGroup);

const socketGroup = new THREE.Group();
const socketBase = new THREE.Mesh(
  new THREE.CylinderGeometry(0.35, 0.42, 0.16, 54),
  new THREE.MeshPhongMaterial({ color: 0xf7f7f7, shininess: 45 })
);
socketBase.position.y = -0.53;
socketGroup.add(socketBase);
const socketTop = new THREE.Mesh(
  new THREE.CylinderGeometry(0.22, 0.31, 0.18, 48),
  new THREE.MeshPhongMaterial({ color: 0xd7d7d7, shininess: 70 })
);
socketTop.position.y = -0.39;
socketGroup.add(socketTop);
const screwNeck = new THREE.Mesh(
  new THREE.CylinderGeometry(0.11, 0.14, 0.22, 32),
  new THREE.MeshPhongMaterial({ color: 0xbfa46a, shininess: 80 })
);
screwNeck.position.y = -0.18;
socketGroup.add(screwNeck);
socketGroup.position.x = -3.82;
scene.add(socketGroup);

const bulbGlass = new THREE.Mesh(
  new THREE.SphereGeometry(0.30, 54, 34),
  new THREE.MeshPhysicalMaterial({
    color: 0xfff1a2,
    transparent: true,
    opacity: 0.42,
    roughness: 0.04,
    metalness: 0,
    transmission: 0.22,
    depthWrite: false
  })
);
bulbGlass.scale.set(0.86, 1.16, 0.86);
bulbGlass.position.set(-3.82, 0.13, 0);
scene.add(bulbGlass);

const bulbTip = new THREE.Mesh(
