  matBasic(0xfff5bc, { transparent: true, opacity: 0.42, depthWrite: false })
);
bulbTip.scale.set(1, 1.5, 1);
bulbTip.position.set(-3.82, 0.47, 0);
scene.add(bulbTip);

const filamentPts = [];
for (let i = 0; i < 34; i++) {
  const t = i / 33;
  filamentPts.push(new THREE.Vector3(
    -3.82,
    -0.02 + 0.045 * Math.sin(t * Math.PI * 8),
    -0.13 + 0.26 * t
  ));
}
scene.add(new THREE.Line(
  new THREE.BufferGeometry().setFromPoints(filamentPts),
