const preBeam = makeTaperedRibbon(-3.52, -2.43, 0.14, 0.20, 0.040, 0.47);
const midBeam = makeTaperedRibbon(-2.34, 2.60, 0.20, 0.23, 0.055, 0.46);
const outBeam = makeTaperedRibbon(2.64, 4.56, 0.21, 0.045, 0.048, 0.52);

const unpolarizedGroup = new THREE.Group();
const unpolarizedAngles = [0, 30, 60, 90, 120, 150];
const unpolarizedOffsets = [
  [0.00, 0.00, 0.00],
  [0.03, 0.19, 0.04],
  [-0.02, -0.17, -0.03],
  [0.02, 0.08, -0.20],
  [-0.03, -0.03, 0.22],
  [0.02, 0.25, -0.15]
