unpolarizedAngles.forEach((ang, i) => {
  const a = createDoubleArrow(0.36, 0.014, red, 1);
  a.position.set(-3.10 + unpolarizedOffsets[i][0], 0.34 + unpolarizedOffsets[i][1], unpolarizedOffsets[i][2]);
  setArrowAngle(a, ang);
  unpolarizedGroup.add(a);
});
scene.add(unpolarizedGroup);

const polFace = makeDiscFace(-2.35, 0.50, 0xb6c987, 0.88);
const polRimOuter = makeRim(-2.35, 0.55, 0.056);
const polRimInner = makeRim(-2.35, 0.47, 0.018);
const polStripes = makeStripeGroup(-2.255, 0.49, 0.032, 0x171717, 0x6f8f54, 0.98);

const postArrows = [];
[-1.92, -1.52].forEach(x => {
  const a = createDoubleArrow(0.72, 0.018, red, 1);
  a.position.set(x, 0, -0.025);
  setArrowAngle(a, 0);
