const tubeGroup = new THREE.Group();
const tubeMat = new THREE.MeshPhysicalMaterial({
  color: glassColor,
  transparent: true,
  opacity: 0.35,
  roughness: 0.08,
  transmission: 0.28,
  side: THREE.DoubleSide,
