  const intensity = Math.cos(diff) * Math.cos(diff);
  outBeam.material.opacity = 0.13 + 0.48 * intensity;
  outBeam.material.needsUpdate = true;
  setGroupOpacity(outgoingArrow, 0.38 + 0.62 * intensity);

  updateArc(analyzerAngle);
}

