function makeStripeGroup(x, radius, spacing, colorA, colorB, opacity = 1) {
  const g = new THREE.Group();
  g.position.set(x, 0, 0);
  let idx = 0;
  for (let z = -radius * 0.88; z <= radius * 0.88 + 1e-6; z += spacing) {
    const yLen = Math.sqrt(Math.max(0, radius * radius - z * z)) * 0.94;
    const pts = [new THREE.Vector3(0, -yLen, z), new THREE.Vector3(0, yLen, z)];
    const line = new THREE.Line(
      new THREE.BufferGeometry().setFromPoints(pts),
      lineMat(idx % 2 ? colorA : colorB, { transparent: opacity < 1, opacity })
    );
    g.add(line);
    idx++;
  }
  scene.add(g);
  return g;
}

