scene.add(new THREE.AmbientLight(0xffffff, 1.22));
const lampLight = new THREE.PointLight(0xfff18a, 1.45, 4.8);
lampLight.position.set(-3.82, 0.12, 0.18);
scene.add(lampLight);
const keyLight = new THREE.DirectionalLight(0xffffff, 1.05);
keyLight.position.set(1.2, 3.4, 4.2);
