function matBasic(color, opts = {}) {
  return new THREE.MeshBasicMaterial({
    color,
    transparent: opts.transparent ?? false,
    opacity: opts.opacity ?? 1,
    side: opts.side ?? THREE.FrontSide,
    depthWrite: opts.depthWrite ?? true
  });
}

function lineMat(color, opts = {}) {
  return new THREE.LineBasicMaterial({
    color,
    transparent: opts.transparent ?? false,
    opacity: opts.opacity ?? 1
  });
}

function createDoubleArrow(length = 0.35, shaftRadius = 0.018, color = red, opacity = 1) {
  const g = new THREE.Group();
  const coneH = length * 0.18;
  const shaftLen = Math.max(0.01, length - 2 * coneH);
  const material = matBasic(color, { transparent: opacity < 1, opacity });
  const shaft = new THREE.Mesh(new THREE.CylinderGeometry(shaftRadius, shaftRadius, shaftLen, 14), material);
  g.add(shaft);
  const coneTop = new THREE.Mesh(new THREE.ConeGeometry(shaftRadius * 3.15, coneH, 20), material);
  coneTop.position.y = length / 2 - coneH / 2;
  g.add(coneTop);
  const coneBot = new THREE.Mesh(new THREE.ConeGeometry(shaftRadius * 3.15, coneH, 20), material);
  coneBot.position.y = -length / 2 + coneH / 2;
  coneBot.rotation.z = Math.PI;
  g.add(coneBot);
  return g;
}

function setArrowAngle(group, deg) {
  group.rotation.x = -THREE.MathUtils.degToRad(deg);
}

function setGroupOpacity(group, opacity) {
  group.traverse(obj => {
    if (obj.material) {
      obj.material.transparent = opacity < 1;
      obj.material.opacity = opacity;
      obj.material.needsUpdate = true;
    }
  });
}

function makeTaperedRibbon(x0, x1, h0, h1, zHalf = 0.045, opacity = 0.48) {
  const verts = new Float32Array([
    x0, -h0, -zHalf,  x1, -h1, -zHalf,  x1,  h1, -zHalf,  x0,  h0, -zHalf,
    x0, -h0,  zHalf,  x1, -h1,  zHalf,  x1,  h1,  zHalf,  x0,  h0,  zHalf
  ]);
  const idx = [
    0, 1, 2, 0, 2, 3,
    4, 6, 5, 4, 7, 6,
    0, 4, 5, 0, 5, 1,
    3, 2, 6, 3, 6, 7,
    1, 5, 6, 1, 6, 2,
    0, 3, 7, 0, 7, 4
  ];
  const geom = new THREE.BufferGeometry();
  geom.setAttribute('position', new THREE.BufferAttribute(verts, 3));
  geom.setIndex(idx);
  geom.computeVertexNormals();

  const group = new THREE.Group();
  const core = new THREE.Mesh(
    geom,
    matBasic(beamColor, { transparent: true, opacity, side: THREE.DoubleSide, depthWrite: false })
  );
  group.add(core);

  const halo = new THREE.Mesh(
    geom.clone(),
    matBasic(beamColor, { transparent: true, opacity: opacity * 0.25, side: THREE.DoubleSide, depthWrite: false })
  );
  halo.scale.set(1, 1.42, 1.55);
  group.add(halo);

  scene.add(group);
  group.core = core;
  group.halo = halo;
  return group;
}

function makeDiscFace(x, radius, color, opacity = 0.88) {
  const mesh = new THREE.Mesh(
    new THREE.CylinderGeometry(radius, radius, 0.16, 96),
    new THREE.MeshBasicMaterial({ color, transparent: opacity < 1, opacity, side: THREE.DoubleSide, depthWrite: false })
  );
  mesh.rotation.z = Math.PI / 2;
  mesh.position.x = x;
  scene.add(mesh);
  return mesh;
}

function makeRim(x, radius, tubeRadius = 0.055) {
  const rim = new THREE.Mesh(
    new THREE.TorusGeometry(radius, tubeRadius, 18, 128),
    matBasic(rimColor)
  );
  rim.rotation.y = Math.PI / 2;
  rim.position.x = x;
  scene.add(rim);
  return rim;
}

function makeStripeGroup(x, radius, spacing, colorA, colorB, opacity = 1) {
  const g = new THREE.Group();
  g.position.set(x, 0, 0);
  let idx = 0;
  for (let z = -radius * 0.90; z <= radius * 0.90 + 1e-6; z += spacing) {
    const yLen = Math.sqrt(Math.max(0, radius * radius - z * z)) * 0.96;
    const line = new THREE.Line(
      new THREE.BufferGeometry().setFromPoints([
        new THREE.Vector3(0, -yLen, z),
        new THREE.Vector3(0,  yLen, z)
      ]),
      lineMat(idx % 2 ? colorA : colorB, { transparent: opacity < 1, opacity })
    );
    g.add(line);
    idx++;
  }
  scene.add(g);
  return g;
}

