addLabel('Polarizer', new THREE.Vector3(-2.35, -0.88, -0.02), { fontSize: '22px' });
addLabel('Polarized<br>light', new THREE.Vector3(-1.35, 1.12, -0.05), { fontSize: '22px' });
addLabel('Sample tube containing<br>organic molecules', new THREE.Vector3(-0.16, -1.15, 0.10), { fontSize: '21px' });
addLabel('Analyzer', new THREE.Vector3(2.65, -0.91, -0.02), { fontSize: '22px' });
addLabel('&alpha;', new THREE.Vector3(4.25, 0.68, -0.12), { fontSize: '22px', bold: true });
