const analyzerSlider = document.getElementById('analyzerAngle');
const sampleSlider = document.getElementById('sampleOpticalActivity');
const analyzerVal = document.getElementById('analyzerAngleVal');
const sampleVal = document.getElementById('sampleOpticalActivityVal');
const pulseButton = document.getElementById('lightPulse');
const narration = document.getElementById('stepNarration');

let analyzerAngle = Number(analyzerSlider.value);
let sampleOpticalActivity = Number(sampleSlider.value);
let pulseStart = performance.now();
let pulseRunning = false;
let tween = null;

function updateAlphaConstruction(angleDeg) {
  const center = alphaCenter;
  const r = 0.55;
  const rad = THREE.MathUtils.degToRad(angleDeg);

  const endRay = new THREE.Vector3(center.x, center.y + r * Math.cos(rad), center.z - r * Math.sin(rad));
  slantedRefGeom.setFromPoints([
    new THREE.Vector3(center.x, center.y, center.z),
    new THREE.Vector3(center.x, center.y + 0.72 * Math.cos(rad), center.z - 0.72 * Math.sin(rad))
  ]);
  slantedRefGeom.computeBoundingSphere();

  const pts = [];
  const steps = Math.max(10, Math.ceil(Math.abs(angleDeg) / 4));
  for (let i = 0; i <= steps; i++) {
    const t = rad * (i / steps);
    pts.push(new THREE.Vector3(center.x, center.y + r * Math.cos(t), center.z - r * Math.sin(t)));
  }
  arcGeom.setFromPoints(pts);
  arcGeom.computeBoundingSphere();

  const sign = rad < 0 ? -1 : 1;
  const tangent = new THREE.Vector3(0, -Math.sin(rad) * sign, -Math.cos(rad) * sign).normalize();
  arcHead.position.copy(endRay);
  arcHead.quaternion.setFromUnitVectors(new THREE.Vector3(0, 1, 0), tangent);
  arcHead.visible = Math.abs(angleDeg) > 2;
}

function updateSceneFromControls() {
  analyzerAngle = Number(analyzerSlider.value);
  sampleOpticalActivity = Number(sampleSlider.value);
  analyzerVal.textContent = analyzerAngle.toFixed(0);
  sampleVal.textContent = sampleOpticalActivity.toFixed(0);

  analyzerStripes.rotation.x = -THREE.MathUtils.degToRad(analyzerAngle);
  tubeArrows.forEach(({ group, fraction }) => setArrowAngle(group, sampleOpticalActivity * fraction));
  setArrowAngle(finalBeforeAnalyzerArrow, sampleOpticalActivity);
  setArrowAngle(outgoingArrow, analyzerAngle);

  const diff = THREE.MathUtils.degToRad(analyzerAngle - sampleOpticalActivity);
  const intensity = Math.cos(diff) * Math.cos(diff);
  outBeam.core.material.opacity = 0.13 + 0.49 * intensity;
  outBeam.halo.material.opacity = 0.04 + 0.16 * intensity;
  outBeam.core.material.needsUpdate = true;
  outBeam.halo.material.needsUpdate = true;
  setGroupOpacity(outgoingArrow, 0.38 + 0.62 * intensity);

  updateAlphaConstruction(analyzerAngle);
}

analyzerSlider.addEventListener('input', () => {
  tween = null;
  updateSceneFromControls();
});
sampleSlider.addEventListener('input', () => {
  tween = null;
  updateSceneFromControls();
});

pulseButton.addEventListener('click', () => {
  pulseRunning = !pulseRunning;
  pulseStart = performance.now();
  pulseButton.classList.toggle('active', pulseRunning);
  pulseButton.textContent = pulseRunning ? 'Hide light pulse' : 'Send light pulse';
});

const steps = [
  {
    title: 'No optical rotation',
    narration: 'With optical activity set to 0°, the arrows after the polarizer remain vertical throughout the sample tube. The analyzer is also vertical when α=0°, so it is aligned with the unchanged polarization plane.',
    state: { sampleOpticalActivity: 0, analyzerAngle: 0 }
  },
  {
    title: 'Sample rotates the plane',
    narration: 'Set the sample to +30°. The red arrows inside the tube twist progressively, ending at a +30° tilted plane before the analyzer.',
    state: { sampleOpticalActivity: 30, analyzerAngle: 0 }
  },
  {
    title: 'Analyzer finds α',
    narration: 'Rotate the analyzer to +30°. Its stripes and outgoing red arrow now match the final polarization plane, so the measured angle α equals the sample-imposed rotation.',
    state: { sampleOpticalActivity: 30, analyzerAngle: 30 }
  },
  {
    title: 'Opposite optical activity',
    narration: 'A negative optical activity twists the arrows the other way. The analyzer must be rotated to the same negative angle to recover maximum transmission.',
    state: { sampleOpticalActivity: -30, analyzerAngle: -30 }
  }
];

window.goToStep = function goToStep(i) {
  const step = steps[i];
  if (!step) return;
  tween = {
    start: performance.now(),
    duration: 850,
    fromAnalyzer: Number(analyzerSlider.value),
    fromSample: Number(sampleSlider.value),
    toAnalyzer: step.state.analyzerAngle,
    toSample: step.state.sampleOpticalActivity
  };
  narration.innerHTML = `<strong>${step.title}</strong><br>${step.narration}`;
};

for (let i = 0; i < steps.length; i++) {
  document.getElementById(`step${i}`).addEventListener('click', () => window.goToStep(i));
}

function updatePulse(now) {
  if (!pulseRunning) {
    pulsePacket.visible = false;
    pulseSingleArrow.visible = false;
    pulseMulti.visible = false;
    return;
  }

  const period = 5200;
  const u = ((now - pulseStart) % period) / period;
  const x = -3.45 + u * 7.85;
  pulsePacket.visible = true;
  pulsePacket.position.set(x, 0.02, 0.045);

  const beforePolarizer = x < -2.35;
  pulseMulti.visible = beforePolarizer;
  pulseSingleArrow.visible = !beforePolarizer;

  if (beforePolarizer) {
    pulseMulti.position.set(x, 0.03, 0.070);
  } else {
    pulseSingleArrow.position.set(x, 0.03, 0.070);
    let angle = 0;
    if (x >= -1.55 && x <= 1.35) {
      angle = sampleOpticalActivity * ((x + 1.55) / 2.90);
    } else if (x > 1.35 && x < 2.65) {
      angle = sampleOpticalActivity;
    } else if (x >= 2.65) {
      angle = analyzerAngle;
    }
    setArrowAngle(pulseSingleArrow, angle);

    const diff = THREE.MathUtils.degToRad(analyzerAngle - sampleOpticalActivity);
    const intensity = x >= 2.65 ? Math.max(0.24, Math.cos(diff) * Math.cos(diff)) : 1;
    pulsePacket.material.opacity = 0.42 + 0.50 * intensity;
    pulsePacket.material.needsUpdate = true;
    setGroupOpacity(pulseSingleArrow, x >= 2.65 ? 0.45 + 0.55 * intensity : 1);
  }
}

function interactionTick(now) {
  if (tween) {
    const t = Math.min(1, (now - tween.start) / tween.duration);
    const eased = t * t * (3 - 2 * t);
    analyzerSlider.value = tween.fromAnalyzer + (tween.toAnalyzer - tween.fromAnalyzer) * eased;
    sampleSlider.value = tween.fromSample + (tween.toSample - tween.fromSample) * eased;
    updateSceneFromControls();
    if (t >= 1) {
      analyzerSlider.value = tween.toAnalyzer;
      sampleSlider.value = tween.toSample;
      updateSceneFromControls();
      tween = null;
    }
  }
  updatePulse(now);
  requestAnimationFrame(interactionTick);
}

updateSceneFromControls();
updatePulse(performance.now());
requestAnimationFrame(interactionTick);
// @FIGURE_CODE_END

